export const MANUAL_EMPLOYEE: Block[] = [
  {"type": "heading", "level": 1, "id": "sec-4", "number": "4", "text": "Employee Mobile"},
  {"type": "note", "text": "Employee accounts are created by the HR administrator (Figure 2.3.2). The employee side is used in the E-TALA mobile app on a phone with its camera and location turned on, because every time in and time out is checked by face and by location."},
  {"type": "heading", "level": 2, "id": "sec-4-1", "number": "4.1", "text": "Getting Started: Login In and First-Time Setup"},
  {"type": "figure", "id": "fig-4-1-1", "number": "4.1.1", "caption": "Logging in", "images": [{ source: require("./fig-4-1-1.png"), width: 1318, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Log In screen", "text": "The screen the app opens to. Type your Email Address and your Password. The eye icon shows or hides what you typed. Tap Log In to sign in. Forgot your password? lets you reset it (Figure 4.1.3)."}, {"n": "2", "title": "Enter your details", "text": "Type the email address the HR administrator registered for you and, the first time, the temporary password from your welcome email (3). Then tap Log In. A first-time login opens Set Your Password (Figure 4.1.2)."}, {"n": "3", "title": "Welcome email", "text": "When the HR administrator adds you, an email titled Your New Account Details and First-Time Login Instructions is sent to your email address. It shows your username, which is your email address, and a temporary password. You are required to set your own password before you can continue."}]},
  {"type": "note", "text": "If the HR administrator has not added you as an employee yet, there is no account to log in to. Ask HR to add you in Employee Management (Figure 2.3.2)."},
  {"type": "figure", "id": "fig-4-1-2", "number": "4.1.2", "caption": "Setting your password and accepting the data privacy consent", "images": [{ source: require("./fig-4-1-2.png"), width: 1318, height: 565 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Set Your Password", "text": "Appears after your first login. Enter the Default Password (the temporary password from the email), a New Password and the same password again under Confirm New Password. The checklist below the fields shows what is still missing: at least 10 characters, a letter, a number, and letters and numbers only. Set Password stays greyed out until every item is met."}, {"n": "2", "title": "Password ready", "text": "When every item in the checklist is ticked, Password Strength is shown (for example Strong) and Set Password turns dark blue. Tap it to save your new password."}, {"n": "3", "title": "Password Set", "text": "“Your password has been saved. Please log in again using your new password.” appears. Tap OK to return to the Log In screen."}, {"n": "4", "title": "Log in again", "text": "Type your email address and your new password, then tap Log In."}, {"n": "5", "title": "Data Privacy Consent", "text": "Read the consent and scroll through Your rights. It explains that your personal information, including facial biometric data, geolocation, attendance and leave records, is used for attendance monitoring and leave management under the Data Privacy Act of 2012 (Republic Act No. 10173), and is accessed only by authorized personnel such as your supervisor and the HR administrator. Tap I Agree to give your consent. You may review this consent again anytime from Settings."}]},
  {"type": "note", "text": "The HR administrator cannot register your face until you tap I Agree. Once you agree, your face is registered on the web (Figure 2.4.2). The registered photo is what the app compares against at every time in and time out."},
  {"type": "figure", "id": "fig-4-1-3", "number": "4.1.3", "caption": "Resetting a forgotten password", "images": [{ source: require("./fig-4-1-3.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Forgot your password?", "text": "On the Log In screen, type your email address, then tap the Forgot your password? link."}, {"n": "2", "title": "Enter Verification Code", "text": "A 6-digit code is sent to your email address. It expires in 10 minutes. Resend code becomes available after the countdown. Tap the back arrow to return to the Log In screen."}, {"n": "3", "title": "Reset code email", "text": "Open the email titled Your password reset code. It shows your 6-digit code and says that it expires in 10 minutes. If you did not ask for it, ignore the email."}, {"n": "4", "title": "Type the code", "text": "Type the 6-digit code in Verification Code and tap Verify Code."}, {"n": "5", "title": "Create New Password", "text": "Type a New Password and type it again under Confirm New Password. Your new password must be different from the passwords you used before. Tap Update Password."}, {"n": "6", "title": "Password Updated", "text": "“You can now log in with your new password.” appears. Tap OK to return to the Log In screen."}, {"n": "7", "title": "Log in", "text": "Type your email address and your new password, then tap Log In."}]},
  {"type": "note", "text": "The web login resets a forgotten password in the same way, with a 6-digit code sent to the email address (Figure 1.2)."},
  {"type": "heading", "level": 2, "id": "sec-4-2", "number": "4.2", "text": "The Main Screens"},
  {"type": "figure", "id": "fig-4-2", "number": "4.2", "caption": "The main screens of the app", "images": [{ source: require("./fig-4-2.png"), width: 1318, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance", "text": "Your starting screen. The top shows your name, the EMPLOYEE badge and the bell. The Attendance Status card shows today’s date, whether you are Not Timed In, Timed In or Day Completed, and your Time In and Time Out. TIME IN and TIME OUT are below it. If you are outside your assigned work area, a red message says so and TIME IN stays greyed out (Figure 4.3.1)."}, {"n": "2", "title": "Leave", "text": "Has three tabs: Balance, Request and Undertime. Balance shows My Leave Balance: how many requests are pending, your Remaining, Earned and Used days, and each leave type with the days used and a Request button. View Filed Leave opens your requests (Figure 4.5.1). Request files a leave (Figure 4.5.2) and Undertime files an undertime (Figure 4.5.4)."}, {"n": "3", "title": "DTR", "text": "Your Daily Time Record. Choose Office or Field, set the From and To dates, and tap a day to open it. Each day shows its status, such as Leave pending or Absent (Figure 4.4.1)."}, {"n": "4", "title": "Work Area", "text": "Shows the work area assigned to you and its Authorized radius. The map shows the work area as a blue circle and your location as a pin, so you can see whether you are inside before you time in. Use + and – to zoom."}, {"n": "5", "title": "Settings", "text": "Shows your name and email address. The list opens My Profile, My Schedule, Change Password, Help and About. Log out signs you out of the app."}, {"n": "6", "title": "Notifications", "text": "Tap the bell to open it. Search notifications, or tap All, Leave, Attendance, Undertime, Announcements or Other to see one kind. A red dot marks what you have not read, and Mark All as Read clears it. Tap a notification to open it. Tap the back arrow to return."}]},
  {"type": "note", "text": "The five tabs at the bottom of every screen (Attendance, Leave, DTR, Work Area and Settings) move you between these screens. The number on the bell is how many notifications are unread."},
  {"type": "heading", "level": 2, "id": "sec-4-3", "number": "4.3", "text": "Attendance with Face Verification and Geotagging"},
  {"type": "figure", "id": "fig-4-3-1", "number": "4.3.1", "caption": "Timing in", "images": [{ source: require("./fig-4-3-1.png"), width: 1479, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, before time in", "text": "The Attendance Status card shows Not Timed In and a dash for Time In and Time Out. Make sure your location and camera permissions are turned on, as the reminder says. Tap TIME IN. TIME OUT stays greyed out until you have timed in."}, {"n": "2", "title": "Time In Verification", "text": "The camera opens for a secure face check with location confirmation. Line your face up with the outline and blink once to confirm. The message at the bottom tells you what the camera sees, for example No face detected until your face is in the outline. The photo is stamped with TIME IN, the date and time, and the address where you are. Tap X to cancel."}, {"n": "3", "title": "Time In Recorded", "text": "“Verified at … Your Daily Time Record has been updated. Your face was verified and you’re within your assigned work area.” Tap Done. The status changes to Timed In."}]},
  {"type": "note", "text": "You can only time in inside the work area assigned to you. If you are outside it, TIME IN stays greyed out and a red message tells you to go to your assigned working area (Figure 4.2). If your face cannot be confirmed, see Figure 4.3.5."},
  {"type": "figure", "id": "fig-4-3-2", "number": "4.3.2", "caption": "Starting lunch", "images": [{ source: require("./fig-4-3-2.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, timed in", "text": "The status reads Timed In. Time Worked counts your working time. The card shows your Time In and Time Out, the Official Start Time and Expected Time Out of your shift, and Start Lunch and End Lunch. TIME IN is greyed out. Tap START LUNCH."}, {"n": "2", "title": "Lunch Start Verification", "text": "The same face and location check as time in. The photo is stamped with LUNCH START, the date and time, and the address. The camera shows Face detected, and the message at the bottom says Tracking while the app asks you to blink to verify you are not a photo."}, {"n": "3", "title": "Lunch Break Start Recorded", "text": "The confirmation shows the time the lunch break started was verified and that your Daily Time Record has been updated. Tap Done."}]},
  {"type": "figure", "id": "fig-4-3-3", "number": "4.3.3", "caption": "Ending lunch", "images": [{ source: require("./fig-4-3-3.png"), width: 1551, height: 622 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, on lunch", "text": "Time Worked (On Lunch) shows that you are on your lunch break. Start Lunch shows the time you started and End Lunch is still a dash. When you are back, tap END LUNCH."}, {"n": "2", "title": "Lunch End Verification", "text": "The same face and location check. The photo is stamped with LUNCH END, the date and time, and your location."}, {"n": "3", "title": "Lunch Break End Recorded", "text": "The confirmation shows the time the lunch break ended was verified. Tap Done. Time Worked continues."}]},
  {"type": "note", "text": "Both lunch times are saved in your Daily Time Record (Figure 4.4.1). Once both are recorded, the lunch button reads LUNCH COMPLETED and is greyed out."},
  {"type": "figure", "id": "fig-4-3-4", "number": "4.3.4", "caption": "Timing out", "images": [{ source: require("./fig-4-3-4.png"), width: 1318, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, timed in", "text": "Time Worked shows how long you have worked today. The card shows your Time In, the Official Start Time, the Expected Time Out and your lunch times. Tap TIME OUT."}, {"n": "2", "title": "Time Out Early?", "text": "Appears when you time out before your Expected Time Out. It shows how much time is left before then, the time you would time out now and the Expected time out. This will be recorded as an early time out and can’t be undone. Tap Time Out Anyway to continue or Cancel to stay timed in."}, {"n": "3", "title": "Time Out Verification", "text": "The same face and location check. The photo is stamped with TIME OUT, the date and time, and your location."}, {"n": "4", "title": "Time Out Recorded", "text": "Confirms that you were verified, that your Daily Time Record has been updated and that you are within your assigned work area. Tap Done."}, {"n": "5", "title": "Day Completed", "text": "The status changes to Day Completed. The card shows your Total Time Worked, Time In, Time Out and lunch times. TIME IN, TIME OUT and the lunch button are greyed out for the rest of the day."}]},
  {"type": "figure", "id": "fig-4-3-5", "number": "4.3.5", "caption": "When your face cannot be confirmed", "images": [{ source: require("./fig-4-3-5.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Unable to Confirm It’s You", "text": "Appears when the app could not clearly confirm that it is you. Make sure you are well lit and facing the camera, then tap Close and try again."}, {"n": "2", "title": "Still Unable to Confirm It’s You", "text": "Appears on your second unclear attempt today. One more, and your supervisor will be notified to review the attendance. Try again in better lighting."}, {"n": "3", "title": "Supervisor Notified", "text": "Appears on your third unclear attempt today. Your supervisor has been notified and will need to review and approve the attendance manually. Tap Close."}]},
  {"type": "note", "text": "The attempt is sent to your supervisor and the HR administrator as a flagged attendance attempt. They compare your captured photo with your registered photo and either validate it or reject it (Figure 2.7.3 and Figure 3.6.2)."},
  {"type": "figure", "id": "fig-4-3-6", "number": "4.3.6", "caption": "When attendance is disabled", "images": [{ source: require("./fig-4-3-6.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, disabled", "text": "This follows the unclear attempts in Figure 4.3.5. If your supervisor has not yet reviewed the attempts, attendance stays disabled until they do. A red message says that repeated unauthorized time in attempts were detected on your account, that your supervisor has been notified, and that attendance is disabled until they review it. TIME IN stays greyed out."}, {"n": "2", "title": "Notifications", "text": "Open the bell and tap Attendance. The notification Attendance Disabled — Report to Your Supervisor is listed with the time it was sent."}, {"n": "3", "title": "Notification details", "text": "Tap the notification to read it in full, with its date and time. Tap X to close it. Report to your supervisor so they can review the attempts."}]},
  {"type": "figure", "id": "fig-4-3-7", "number": "4.3.7", "caption": "When your attendance is validated", "images": [{ source: require("./fig-4-3-7.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Attendance, timed in", "text": "After your supervisor or the HR administrator validates the attempt, the Attendance Status card changes to Timed In. The Time In of the attempt is recorded and Time Worked starts counting."}, {"n": "2", "title": "Notifications", "text": "The notification Attendance Validated is added to the list. A red dot marks it as unread and the number beside Notifications shows how many are unread. Mark All as Read clears them."}, {"n": "3", "title": "Notification details", "text": "Tap the notification to read it. It says that your attendance attempt for that date was reviewed and validated, and that it has been recorded. Tap X to close it."}]},
  {"type": "note", "text": "The supervisor or HR administrator validates an attempt with Validate as Legitimate (Figure 2.7.3 and Figure 3.6.2)."},
  {"type": "heading", "level": 2, "id": "sec-4-4", "number": "4.4", "text": "Daily Time Record"},
  {"type": "figure", "id": "fig-4-4-1", "number": "4.4.1", "caption": "Daily Time Record: Office", "images": [{ source: require("./fig-4-4-1.png"), width: 1318, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Daily Time Record list", "text": "The Office tab lists your days, newest first, grouped by month with the number of records. Each day shows its date, the leave type or site, and its status in colour, such as Leave pending, Absent or On leave. Set From and To to show a range of dates. Tap a month to open or close it."}, {"n": "2", "title": "Leave pending", "text": "Tap a day to open it. A day with a leave request that has not been decided says that your request is still awaiting a decision and that no attendance has been logged. It shows your scheduled shift, the leave type and that no time in or out was logged. It will be recorded as an absence only if the request is not approved and you did not report for work."}, {"n": "3", "title": "Absent", "text": "A day with no attendance says that no attendance was logged on that day, so it is recorded as an absence. It shows your scheduled shift and that no time in or out was logged."}, {"n": "4", "title": "On leave", "text": "A day of approved leave says that you were on approved leave on that day, so no attendance was required. It shows your scheduled shift and the leave type."}, {"n": "5", "title": "Attended day", "text": "A day you attended shows the total time worked, the site, your Time In, Time Out and Lunch Break. Tap View captured photos to see the photos taken at each time in, lunch and time out (Figure 4.4.2)."}]},
  {"type": "figure", "id": "fig-4-4-2", "number": "4.4.2", "caption": "Viewing captured photos", "images": [{ source: require("./fig-4-4-2.png"), width: 1517, height: 633 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Time In", "text": "Tap View captured photos on a day you attended. A window opens with the date and the site, and a tab for each photo: Time In, Start Lunch, End Lunch and Time Out. Time In shows the photo taken when you timed in, stamped with TIME IN, the date and time, and the address. Tap Close to leave."}, {"n": "2", "title": "Start Lunch", "text": "Tap Start Lunch to see the photo taken when your lunch break started, stamped with START LUNCH."}, {"n": "3", "title": "End Lunch", "text": "Tap End Lunch to see the photo taken when your lunch break ended, stamped with END LUNCH."}, {"n": "4", "title": "Time Out", "text": "Tap Time Out to see the photo taken when you timed out, stamped with TIME OUT."}]},
  {"type": "note", "text": "These are the photos taken at each face and location check (Figure 4.3.1 to Figure 4.3.4). Your supervisor and the HR administrator see the same photos in Attendance Details (Figure 2.7.2 and Figure 3.6.1)."},
  {"type": "figure", "id": "fig-4-4-3", "number": "4.4.3", "caption": "Daily Time Record: Field", "images": [{ source: require("./fig-4-4-3.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Field tab", "text": "For employees whose attendance mode includes Field. It lists your days, newest first, grouped by month with the number of records. Tap a day to open it. It shows the time your Visit Start and Visit End were recorded and a View captured photos button. Use From and To to set the dates, and All, AM or PM to show visits in the morning or afternoon."}, {"n": "2", "title": "Visit End", "text": "Tap View captured photos. Visit End shows the photo taken when you ended the visit, stamped with the date, time and address. Tap Close to go back."}, {"n": "3", "title": "Visit Start", "text": "Tap Visit Start to see the photo taken when you started the visit, stamped with the date, time and address."}]},
  {"type": "note", "text": "A field visit is started and ended in the same way as timing in and timing out (Figure 4.3.1 and Figure 4.3.4). The app opens the camera for the face and location check, and the photo is stamped with the date, time and address. The Visit Start and Visit End photos are the photos taken at those two checks."},
  {"type": "heading", "level": 2, "id": "sec-4-5", "number": "4.5", "text": "Leave and Undertime"},
  {"type": "figure", "id": "fig-4-5-1", "number": "4.5.1", "caption": "Leave balance and your filed leave requests", "images": [{ source: require("./fig-4-5-1.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Leave balance", "text": "The Balance tab of Leave. The ring shows the percentage of your leave used. Remaining, Earned and Used are your totals for the year, and a Pending chip shows how many requests are waiting for a decision. Below are your leave types, each with a bar, the days used and a Request button. Tap View Filed Leave to open your requests."}, {"n": "2", "title": "My Leave Requests", "text": "Current lists the requests still waiting for a decision and Past lists the decided ones, each with the number of requests. Tap All, Pending, Approved, Rejected, Cancelled or Lapsed to show one status, or set Filed from and Filed to. Tap a request to open it. Tap Close to leave."}, {"n": "3", "title": "Leave Request Details", "text": "Shows the leave type, the dates and the status. Approval Progress shows when the request was Filed and any document you attached, and that it is waiting for review by your supervisor or HR. Cancel Leave withdraws a request that is still pending. Tap All requests to go back to the list."}]},
  {"type": "figure", "id": "fig-4-5-2", "number": "4.5.2", "caption": "Filing a leave request", "images": [{ source: require("./fig-4-5-2.png"), width: 1524, height: 611 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Leave Type", "text": "On the Request tab, tap Leave Type and search or pick a leave type. A leave type that needs a supporting document is marked document required. One with no days left is greyed out and marked no balance left."}, {"n": "2", "title": "Leave Duration and document", "text": "Choose the From and To dates. The app shows the total days and how many days are available for that leave type, and does not let the end date go past them. Tap to attach a photo or PDF as a Supporting Document, which some leave types require, and type your Reason. Tap Submit Leave Request."}, {"n": "3", "title": "Reason Required", "text": "If the Reason is empty, the app asks you to tell it the reason for your leave. Tap Done, type the reason and submit again."}, {"n": "4", "title": "Leave Request Submitted", "text": "Confirms that your HR administrator and supervisor have been notified and that you will be notified once it is reviewed. Tap Done."}]},
  {"type": "note", "text": "A reviewer can send a request back for more requirements instead of rejecting it. Its status becomes Needs Revision and you are notified in the app. Submit what was asked for and file the request again (Figure 2.8.3)."},
  {"type": "figure", "id": "fig-4-5-3", "number": "4.5.3", "caption": "Viewing decided leave requests", "images": [{ source: require("./fig-4-5-3.png"), width: 1318, height: 529 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "Past requests", "text": "Open View Filed Leave and tap Past. Each decided request shows its leave type, its dates and a status such as Approved or Lapsed. Use the status buttons and the Filed from and Filed to dates to narrow the list."}, {"n": "2", "title": "Approved", "text": "Approval Progress is the timeline of the request: Filed, any additional requirements requested and your resubmission with its document, and Approved with the name of the approver. Cancel Leave is greyed out when the leave type does not allow employees to cancel, and the app tells you to contact HR/Admin."}, {"n": "3", "title": "Rejected", "text": "Shows Filed and Rejected, with the name of the person who rejected it and the reason they gave."}, {"n": "4", "title": "Cancelled", "text": "Shows Filed, Approved, Cancellation requested with your reason, and Cancelled, each with its date, time and the person who acted."}, {"n": "5", "title": "Lapsed", "text": "Shows that the requirements asked for were not submitted before the leave dates passed and that work was reported on those dates, so no leave was used (Figure 3.7.3)."}]},
  {"type": "figure", "id": "fig-4-5-4", "number": "4.5.4", "caption": "Filing undertime", "images": [{ source: require("./fig-4-5-4.png"), width: 1600, height: 642 }]},
  {"type": "callouts", "items": [{"n": "1", "title": "File Undertime", "text": "The Undertime tab of Leave shows the Cutoff period and the days of the month on which undertime can be filed. When there is nothing you can file, it says Nothing to file right now. Tap View My Undertime Request to see your filings."}, {"n": "2", "title": "My Undertime Request", "text": "Lists your filings with the attendance date, the status, the minutes of undertime and your reason. Tap All, Pending, Approved or Rejected to show one status, or set Filed from and Filed to. Tap Close to leave."}, {"n": "3", "title": "Undertime Filing Details", "text": "Shows the minutes of undertime, the date and the status. Approval Progress shows when it was Filed with your reason, and who approved or rejected it. Tap All filings to go back."}]},
  {"type": "note", "text": "The filing days and cutoff periods are set by the HR administrator (Figure 2.11.2). Your supervisor and the HR administrator review the filing (Figure 3.7.8)."},
];
